/**
 * Expo config plugin: puts AuCourant's Java layer into the generated android/ project.
 *
 * android/ is generated by `expo prebuild` (Continuous Native Generation) and is not
 * committed. The Java sources live in native/android/java and this plugin, on every
 * prebuild:
 *   1. copies them into android/app/src/main/java,
 *   2. registers AuCourantPackage in MainApplication,
 *   3. adds the FileProvider used to share exported reports.
 */
const fs = require('fs')
const path = require('path')
const { withDangerousMod, withMainApplication, withAndroidManifest, AndroidConfig } = require('expo/config-plugins')

const PKG = 'com.aucourant.nativebridge'
const SRC = path.join('native', 'android', 'java')
const PATHS_XML = 'aucourant_file_paths'

function copyDir(from, to) {
  fs.mkdirSync(to, { recursive: true })
  for (const entry of fs.readdirSync(from, { withFileTypes: true })) {
    const a = path.join(from, entry.name)
    const b = path.join(to, entry.name)
    if (entry.isDirectory()) copyDir(a, b)
    else fs.copyFileSync(a, b)
  }
}

const withJavaSources = (config) =>
  withDangerousMod(config, [
    'android',
    async (cfg) => {
      const root = cfg.modRequest.projectRoot
      const main = path.join(cfg.modRequest.platformProjectRoot, 'app', 'src', 'main')
      copyDir(path.join(root, SRC), path.join(main, 'java'))
      const xmlDir = path.join(main, 'res', 'xml')
      fs.mkdirSync(xmlDir, { recursive: true })
      fs.writeFileSync(
        path.join(xmlDir, `${PATHS_XML}.xml`),
        '<?xml version="1.0" encoding="utf-8"?>\n<paths>\n  <files-path name="exports" path="exports/" />\n</paths>\n',
      )
      return cfg
    },
  ])

const withPackageRegistered = (config) =>
  withMainApplication(config, (cfg) => {
    const src = cfg.modResults.contents
    const line = cfg.modResults.language === 'java' ? `packages.add(new ${PKG}.AuCourantPackage());` : `add(${PKG}.AuCourantPackage())`
    if (src.includes(`${PKG}.AuCourantPackage`)) return cfg
    const anchor = cfg.modResults.language === 'java' ? /(List<ReactPackage> packages = new PackageList\(this\)\.getPackages\(\);)/ : /(PackageList\(this\)\.packages\.apply \{)/
    if (!anchor.test(src)) {
      throw new Error('[with-aucourant-native] Could not find the package list in MainApplication. Update the anchor for this Expo SDK.')
    }
    cfg.modResults.contents = src.replace(anchor, `$1\n              ${line}`)
    return cfg
  })

const withFileProvider = (config) =>
  withAndroidManifest(config, (cfg) => {
    const app = AndroidConfig.Manifest.getMainApplicationOrThrow(cfg.modResults)
    app.provider = app.provider ?? []
    const name = 'androidx.core.content.FileProvider'
    if (!app.provider.some((p) => p.$['android:authorities']?.endsWith('.aucourant.files'))) {
      app.provider.push({
        $: {
          'android:name': name,
          'android:authorities': '${applicationId}.aucourant.files',
          'android:exported': 'false',
          'android:grantUriPermissions': 'true',
        },
        'meta-data': [{ $: { 'android:name': 'android.support.FILE_PROVIDER_PATHS', 'android:resource': `@xml/${PATHS_XML}` } }],
      })
    }
    return cfg
  })

module.exports = (config) => withFileProvider(withPackageRegistered(withJavaSources(config)))
